# %% ../nbs/replay_buffer.ipynb 3
def map_tensors(obj, fn, _cache=None):
    """Apply `fn` to every tensor in a (nested) dict / list / tuple, leaving other values untouched.
    A tensor met several times (consecutive transitions share their middle state) is converted once."""
    if _cache is None:
        _cache = {}
    if isinstance(obj, torch.Tensor):
        key = (obj.data_ptr(), tuple(obj.shape), obj.dtype)
        if key not in _cache:
            _cache[key] = fn(obj)
        return _cache[key]
    if isinstance(obj, dict):
        return {k: map_tensors(v, fn, _cache) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return type(obj)(map_tensors(v, fn, _cache) for v in obj)
    return obj


class PrioritizedReplayBuffer:
    def __init__(
        self,
        capacity,
        queue_capacity=128,
        prob_alpha=0.5,
        e=1e-5,
        beta=1.0,
        beta_increment=1e-5,
        device="cpu",
        demo_priority_bonus=1.0,  # added to the priority of demonstration transitions (DQfD style)
    ):
        store_attr()
        self._nb_demo = 0
        self.experience_queue = queue.Queue(queue_capacity) if USE_THREADS else mp.Queue(queue_capacity)

    def push(self, *args):
        if CPU_TRANSFER:  # no CUDA IPC on Windows: cross the process boundary on the CPU
            args = map_tensors(args, lambda t: t.detach().cpu())
        try:
            self.experience_queue.put(args, False)
        except Full:
            logging.warning("Replay buffer queue is full")

    @cached_property
    def buffer(self):
        return L()

    @cached_property
    def pos(self):
        return 0

    @cached_property
    def priorities(self):
        return torch.zeros(
            (self.capacity,), dtype=torch.float, device=self.device, requires_grad=False
        )

    @cached_property
    def last_insert_time(self):
        return time()

    def empty_queue(self):
        try:
            while True:
                self._push(*self.experience_queue.get(False))
                self.last_insert_time = time()
        except Empty:
            pass

    @cached_property
    def demo(self):
        "Demonstration (protected) slots: never overwritten, priority bonus."
        return torch.zeros((self.capacity,), dtype=torch.bool, device=self.device)

    @cached_property
    def metas(self):
        return [None] * self.capacity

    @cached_property
    def _last_next_state(self):
        return None

    def demo_count(self):
        return self._nb_demo

    def _push(self, state, next_state, action, reward, done, meta=None):
        if CPU_TRANSFER:
            state, next_state = map_tensors((state, next_state), lambda t: t.to(self.device, non_blocking=True))
        last = self._last_next_state
        if last is not None and state is not last and state["env"].get("_updatetime") == last["env"].get("_updatetime"):
            state = last  # consecutive transitions share their middle state: keep a single copy of its frame
        self._last_next_state = next_state
        max_prio = self.priorities.max() if self.buffer else 1.0

        if len(self.buffer) < self.capacity:
            self.buffer.append((state, next_state, action, reward, done))
            idx = len(self.buffer) - 1
        else:
            skipped = 0
            while self.demo[self.pos] and skipped < self.capacity:
                self.pos = (self.pos + 1) % self.capacity
                skipped += 1
            idx = self.pos
            self.buffer[idx] = (state, next_state, action, reward, done)
        is_demo = bool(meta and meta.get("demo"))
        if is_demo and 0.8 * self.capacity <= self._nb_demo:
            if not getattr(self, "_demo_cap_warned", False):
                logging.warning(f"Demonstration slots are full ({self._nb_demo} of {self.capacity} buffer slots): "
                                "further demonstrations are stored as regular, overwritable experiences. "
                                "Increase --buffer to keep more.")
                self._demo_cap_warned = True
            is_demo = False
        self.demo[idx] = is_demo
        self._nb_demo += is_demo
        self.metas[idx] = meta
        self.priorities[idx] = max_prio
        self.pos = (idx + 1) % self.capacity

    def demos(self):
        "Demonstration transitions with their metadata (for saving)."
        idx = self.demo[: len(self.buffer)].nonzero().flatten().tolist()
        return [(self.buffer[i], self.metas[i]) for i in idx]

    def load_demos(self, demos):
        demos = map_tensors(demos, lambda t: t.to(self.device))  # one cache for all: shared frames stay shared
        for transition, meta in demos:
            self._push(*transition, meta=dict(meta or {}, demo=True))
        self.last_insert_time = time()

    def sample(self, batch_size):
        self.beta = min(1.0, self.beta + self.beta_increment)

        prios = self.priorities[: len(self)]
        indices = L(WeightedRandomSampler(prios, batch_size, replacement=False))
        samples = self.buffer[indices]

        total = len(self.buffer)
        weights = (total * (prios / prios.sum())[indices]) ** (-self.beta)
        weights /= weights.max()

        return samples, indices, weights

    def update_priorities(self, indices, errors):
        p = torch.nan_to_num(errors, nan=0.0, posinf=0.0, neginf=0.0)
        p = torch.nn.functional.relu(p)
        if not torch.equal(p, errors):
            logging.warning(
                "Received invalid priority, either `inf`, `nan` or element < 0"
            )
        idx = torch.as_tensor(list(indices), device=self.device)
        bonus = self.demo[idx].float() * self.demo_priority_bonus
        self.priorities[idx] = (p + self.e + bonus) ** self.prob_alpha

    def __len__(self):
        return len(self.buffer)
